args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?bdate WHERE {
  VALUES ?film { <http://dbpedia.org/resource/The_Gamecock_(film)> <http://dbpedia.org/resource/Monster_a_Go-Go> }

  {
    SELECT ?film (MIN(?b) AS ?minBirth) WHERE {
      ?film dbo:director ?d .
      ?d dbo:birthDate ?b .
    } GROUP BY ?film
  }

  ?film dbo:director ?director .
  ?director dbo:birthDate ?bdate .
  FILTER(?bdate = ?minBirth)

  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
} ORDER BY ?film

